int active()
{
    int ret = true;

    ret = next active();

    FormFunctionButtonControl control   = this.formRun().design().controlName(formControlStr(SalesTable, FTDBook));
    SalesTable activeSalesTable     = this.cursor();

    control.enabled(activeSalesTable.FTDBookTable != 0);

    return ret;
}
